mapper.select:
SELECT t1.*, /* (t1.deposit_residual_amount1 - t1.deposit_refund_amount - t1.deposit_deduction_amount) outstanding_deposit*/ ( t1.deposit_residual_amount - t1.deposit_deduction_amount ) outstanding_deposit FROM (SELECT t.*, h.duration_number, c.contract_number, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'DEPOSIT_WFL_STATUS' AND v.code_value = t.execute_status) execute_status_n, (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.bp_id = c.tenant_id) bp_name, nvl((SELECT SUM(nvl(ccc.due_amount, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = t.contract_id AND ccc.cf_item IN (52, 502,54) AND ccc.cf_status = 'RELEASE'), 0)deposit_amount,
nvl((SELECT SUM(nvl(ccc.RECEIVED_AMOUNT, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = t.contract_id AND ccc.cf_item IN (51, 501, 53) AND ccc.cf_status = 'RELEASE'),0)deposit_received_amount,
nvl((SELECT SUM(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = t.contract_id AND ccc.cf_item IN (52, 502,54) AND ccc.cf_status = 'RELEASE'), 0) deposit_residual_amount1,
nvl((SELECT SUM(nvl(ln.refund_amount, 0)) FROM hls_duration_ln ln WHERE ln.hd_id = t.hd_id AND ln.source_type IN ('DEPOSIT', 'INTEREST') AND ln.source_id = t.source_id), 0) deposit_refund_amount,
nvl((SELECT SUM(nvl(ln.deduction_amount, 0)) FROM hls_duration_ln ln WHERE ln.hd_id = t.hd_id AND ln.source_type IN ('DEPOSIT', 'INTEREST') AND ln.source_id = t.source_id), 0) deposit_deduction_amount,
nvl((SELECT SUM(nvl(ln.refund_amount, 0)) FROM hls_duration_ln ln, hls_duration_deposit d WHERE d.source_id = ln.source_id AND d.execute_status = 'APPROVED' AND ln.source_type IN ('DEPOSIT', 'INTEREST')), 0) execute_refund_amount,
nvl((SELECT SUM(nvl(ln.deduction_amount, 0)) FROM hls_duration_ln ln, hls_duration_deposit d WHERE d.source_id = ln.source_id AND d.execute_status = 'APPROVED' AND ln.source_type IN ('DEPOSIT', 'INTEREST')), 0) execute_deduction_amount,
(SELECT a.bank_account_num FROM hls_bp_master_bank_account a WHERE a.bank_account_id = t.bp_bank_account_id) bank_account_num, (SELECT a.bank_account_name FROM hls_bp_master_bank_account a WHERE a.bank_account_id = t.bp_bank_account_id) bank_account_name
FROM hls_duration_deposit t, hls_duration_hd h, con_contract c WHERE h.hd_id = t.hd_id AND t.contract_id = c.contract_id and h.duration_status = 'APPROVED') t1
and t1.duration_number like #{durationNumber}
and t1.contract_number like #{contractNumber}
and t1.bp_name like #{bpName}
and t1.contract_id = #{contractId}

SELECT SUM(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0))deposit_residual_amount FROM con_contract_cashflow ccc,prj_project pp ,con_contract cc
ccc.cf_item IN (52, 502, 54) and cc.contract_id = ccc.contract_id and pp.project_id = cc.project_id AND ccc.cf_status = 'RELEASE'
and pp.project_id = #{projectId}

SELECT SUM(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0))deposit_residual_amount FROM con_contract_cashflow ccc ,con_contract cc
ccc.cf_item IN (52, 502, 54) and cc.contract_id = ccc.contract_id AND ccc.cf_status = 'RELEASE'
and cc.contract_id = #{contractId}
